import random, itertools, sys
sys.setrecursionlimit(100000)
from book_store import total

disc = {1:0,2:5,3:10,4:20,5:25}
def brute(counts):
    books = []
    for i,c in enumerate(counts):
        books += [i]*c
    best = 800*len(books)
    def rec(rem, total_cost):
        nonlocal best
        if not any(rem):
            best = min(best, total_cost); return
        present = [i for i in range(5) if rem[i]>0]
        for r in range(1, len(present)+1):
            for combo in itertools.combinations(present, r):
                nr = list(rem)
                for b in combo: nr[b]-=1
                rec(nr, total_cost + len(combo)*800*(100-disc[len(combo)])//100)
    rec(list(counts), 0)
    return best

random.seed(1)
for t in range(3000):
    counts = [random.randint(0,4) for _ in range(5)]
    if not any(counts): continue
    basket = []
    for i,c in enumerate(counts):
        basket += [i+1]*c
    a = total(basket); b = brute(counts)
    if a != b:
        print('MISMATCH', counts, a, b); break
else:
    print('All 3000 random baskets match brute force.')
"
